from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(T: int) -> bool:
            moves = 0
            carry = 0  # number of times next index has already been visited
            for i in range(n):
                p = points[i]
                need = (T + p - 1) // p  # visits needed at index i
                remaining = need - carry
                if remaining <= 0:
                    # Already satisfied by carried visits.
                    if i == n - 1:
                        # no need to even step into it
                        break
                    # we must still step into i to continue (1 move), no carry benefit beyond
                    moves += 1
                    carry = 0
                else:
                    # step into i once, then (remaining-1) oscillations costing 2 each
                    moves += 1 + 2 * (remaining - 1)
                    carry = remaining - 1
                if moves > m:
                    return False
            return moves <= m

        lo, hi = 0, 10**6 * 10**9 // 1 + 1
        # tighter upper bound: min points * (m+1)//... just keep safe bound
        hi = min(hi, min(points) * ((m + 1) // 2 + 1) + 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        forced = [False] * L

        # Place str2 at all 'T' positions, check for conflicts
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    c = str2[j]
                    if word[i + j] is not None and word[i + j] != c:
                        return ""
                    word[i + j] = c
                    forced[i + j] = True

        # Fill free positions with 'a'
        for i in range(L):
            if word[i] is None:
                word[i] = 'a'

        s2 = list(str2)
        # Fix 'F' positions
        for i in range(n):
            if str1[i] == 'F':
                if word[i:i + m] == s2:
                    # find rightmost free position in window
                    pos = -1
                    for j in range(m - 1, -1, -1):
                        if not forced[i + j]:
                            pos = i + j
                            break
                    if pos == -1:
                        return ""
                    word[pos] = 'b'
                    forced[pos] = True

        return ''.join(word)

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        # mod 9 prefix digit sums
        cnt9 = [0] * 9
        cnt9[0] = 1
        sum9 = 0
        # mod 7 weighted prefix residues
        cnt7 = [0] * 7
        # r_j = P[j] * 10^{-j} mod 7
        P7 = 0  # P[j] mod 7
        pow10 = [1] * 6
        for k in range(1, 6):
            pow10[k] = pow10[k - 1] * 10 % 7
        # inverse of 10^j mod 7: 10^{-j} = 10^{(6 - j%6)%6}
        inv_pow = [pow10[(6 - (j % 6)) % 6] for j in range(6)]
        cnt7[0] += 1  # j=0: P[0]=0, r_0=0
        for i, ch in enumerate(s):
            d = ord(ch) - 48
            # update prefix structures for prefix ending at i (index i+1)
            sum9 = (sum9 + d) % 9
            P7 = (P7 * 10 + d) % 7
            r = P7 * inv_pow[(i + 1) % 6] % 7
            if d == 0:
                pass
            elif d in (1, 2, 5):
                ans += i + 1
            elif d == 3 or d == 6:
                # sum of substring digits mod 3 == 0: count j with P[j] % 3 == sum9 % 3
                target = sum9 % 3
                ans += cnt9[target] + cnt9[target + 3] + cnt9[target + 6]
            elif d == 9:
                ans += cnt9[sum9]
            elif d == 4:
                # last two digits divisible by 4
                if i == 0:
                    ans += 1 if d % 4 == 0 else 0
                else:
                    two = (ord(s[i - 1]) - 48) * 10 + d
                    if two % 4 == 0:
                        ans += i + 1
                    else:
                        ans += 0
                    # single digit substring: d itself; included above if two%4==0 since d even... check
                    # d=4: "4" divisible. two%4==0 iff s[i-1] even. If two%4!=0, single "4" still counts.
                    if two % 4 != 0:
                        ans += 1
            elif d == 8:
                # last three digits divisible by 8
                if i == 0:
                    ans += 1
                elif i == 1:
                    two = (ord(s[i - 1]) - 48) * 10 + d
                    ans += 1 + (1 if two % 8 == 0 else 0)
                else:
                    two = (ord(s[i - 1]) - 48) * 10 + d
                    three = (ord(s[i - 2]) - 48) * 100 + two
                    ans += 1  # single "8"
                    if two % 8 == 0:
                        ans += 1
                    if three % 8 == 0:
                        ans += i - 1
            elif d == 7:
                # substring (j, i] value = P[i+1] - P[j]*10^{i+1-j}; divisible by 7 iff
                # P[i+1]*10^{-(i+1)} == P[j]*10^{-j} mod 7
                ans += cnt7[r]
            cnt9[sum9] += 1
            cnt7[r] += 1
        return ans

