            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = arr[i] + d
                while j < m and arr[j] < target:
                    j += 1
                nxt[i] = j
            for i in range(n):
                limit = arr[i] + P - d
                cur = i
                ok = True
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= m or arr[cur] > limit:
                        ok = False
                        break
                if ok:
                    return True
            return False

        lo, hi = 1, s
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
