from bisect import bisect_left

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        P = 4 * side
        pos = []
        for x, y in points:
            if y == 0:
                pos.append(x)
            elif x == side:
                pos.append(side + y)
            elif y == side:
                pos.append(3 * side - x)
            else:
                pos.append(4 * side - y)
        pos.sort()
        n = len(pos)

        def ok(d):
            for i in range(n):
                start = pos[i]
                limit = start + P - d
                if pos[-1] < start and False:
                    pass
                cur = start
                idx = i
                good = True
                for _ in range(k - 1):
                    idx = bisect_left(pos, cur + d, idx + 1)
                    if idx >= n or pos[idx] > limit:
                        good = False
                        break
                    cur = pos[idx]
                if good:
                    return True
                # if even the first jump from start fails due to n bound, later starts fail too
                if idx >= n:
                    return False
            return False

        lo, hi = 1, P // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

