class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        def can_achieve(target: int) -> bool:
            moves = 0
            carried_visits = 0

            for i, value in enumerate(points):
                required_visits = (target + value - 1) // value
                needed = required_visits - carried_visits

                if needed > 0:
                    # Enter i, then bounce needed - 1 times between
                    # i and i + 1, ending at i.
                    # At the last index, bounce with i - 1 instead.
                    moves += 2 * needed - 1
                    carried_visits = needed - 1
                else:
                    # This index already has enough visits. We only
                    # need to enter it if there are more indices ahead.
                    if i == n - 1:
                        return True
                    moves += 1
                    carried_visits = 0

                if moves > m:
                    return False

            return True

        low = 0
        # An index cannot be visited on consecutive moves.
        high = min(points) * ((m + 1) // 2)

        while low < high:
            mid = (low + high + 1) // 2
            if can_achieve(mid):
                low = mid
            else:
                high = mid - 1

        return low

class Solution:
    def countSubstrings(self, s: str) -> int:
        # dp[d][r]: number of substrings ending at the previous position
        # whose value has remainder r modulo d.
        dp = [[0] * d for d in range(10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                current = [0] * d

                # Extend every substring ending at the previous position.
                for remainder, count in enumerate(dp[d]):
                    current[(remainder * 10 + digit) % d] += count

                # Start a new one-character substring.
                current[digit % d] += 1
                dp[d] = current

            if digit != 0:
                answer += dp[digit][0]

        return answer

