        for i, flag in enumerate(str1):
            if flag == 'F' and word[i:i + m] == pattern:
                pos = i + m - 1
                while pos >= i and fixed[pos]:
                    pos -= 1

                if pos < i:
                    return ""

                word[pos] = 'b'
                fixed[pos] = True

        return ''.join(word)

