class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        # Map boundary points to clockwise positions on the perimeter.
        positions = []
        for x, y in points:
            if x == 0:
                positions.append(y)
            elif y == side:
                positions.append(side + x)
            elif x == side:
                positions.append(3 * side - y)
            else:
                positions.append(perimeter - x)

        positions.sort()
        n = len(positions)
        extended = positions + [p + perimeter for p in positions]
        m = len(extended)
        extended.append(3 * perimeter)  # Sentinel for an unavailable point.

        def feasible(distance: int) -> bool:
            # jump[i] is the earliest point at least distance after point i.
            jump = [m] * (m + 1)
            j = 0
            for i in range(m):
                while j < m and extended[j] - extended[i] < distance:
                    j += 1
                jump[i] = j

            # Greedily select k points from every possible starting point,
            # using binary lifting to perform k - 1 selections.
            endpoints = list(range(n))
            steps = k - 1
            while steps:
                if steps & 1:
                    endpoints = [jump[index] for index in endpoints]
                steps >>= 1
                if steps:
                    jump = [jump[index] for index in jump]

            # The final point must also be far enough from the first
            # across the wraparound gap.
            for start, end in enumerate(endpoints):
                if extended[end] <= positions[start] + perimeter - distance:
                    return True
            return False

        # Circular distance is never smaller than Manhattan distance.
        # Thus k selected points imply distance <= perimeter // k <= side.
        # For distances <= side, the circular and Manhattan constraints
        # are equivalent on the boundary of a square.
        low, high = 0, perimeter // k
        while low < high:
            mid = (low + high + 1) // 2
