class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def enough(x: int) -> bool:
            if x <= 0:
                return True

            # We process adjacent pairs (i, i+1).  `rem` is how much score
            # still has to be added to index i by coming back from i+1 to i.
            # At index i we choose `add` = number of future visits to i+1
            # that will also come back to i, i.e. score[i] gets add*points[i].
            rem = x
            moves = 0

            for i in range(n):
                p = points[i]

                if i == n - 1:
                    # No right neighbour can send score back to the last cell.
                    need = (rem + p - 1) // p
                    moves += need
                else:
                    # One visit to i+1 is unavoidable (to enter the suffix i+1..n-1).
                    # Every further visit to i+1 can be paired with a return to i,
                    # giving points[i] to index i.
                    need = (rem + p - 1) // p
                    if need < 1:
                        need = 1

                    # moves spent while travelling through edge i <-> i+1:
                    # go to i+1 `need` times and return to i `need-1` times.
                    # For i == 0 this includes the initial move from -1 to 0 as well.
                    if i == 0:
                        moves += 2 * need - 1
                    else:
                        moves += 2 * need

                    if moves > m:
                        return False

                    # The `need` arrivals at i+1 give need*points[i+1].
                    # Part of it may be needed by index i+1 itself; the rest is
                    # useless surplus for the left side, so only the deficit is passed on.
                    rem = x - need * points[i + 1]
                    if rem < 0:
                        rem = 0

                if moves > m:
                    return False

            return moves <= m

        lo, hi = 0, max(points) * (m + 1)  # exclusive upper bound
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if enough(mid):
                lo = mid
            else:
                hi = mid
        return lo

