class Solution:
    def countSubstrings(self, s: str) -> int:
        ans = 0

        cnt3 = [1, 0, 0]
        cnt9 = [1] + [0] * 8
        cnt7 = [1] + [0] * 6

        r3 = r9 = 0
        p7 = 0          # prefix value mod 7
        inv10_7 = 1     # 10^{-prefix_len} mod 7

        for i, ch in enumerate(s):
            d = ord(ch) - 48

            r3 = (r3 + d) % 3
            r9 = (r9 + d) % 9

            p7 = (p7 * 3 + d) % 7        # 10 == 3 (mod 7)
            inv10_7 = (inv10_7 * 5) % 7  # 5 == 10^{-1} (mod 7)
            key7 = p7 * inv10_7 % 7

            if d == 1 or d == 2 or d == 5:
                ans += i + 1
            elif d == 3 or d == 6:
                ans += cnt3[r3]
            elif d == 4:
                ans += 1
                if i and ((ord(s[i - 1]) - 48) & 1) == 0:
                    ans += i
            elif d == 8:
                ans += 1
                if i:
                    b = ord(s[i - 1]) - 48
                    if b % 4 == 0:
                        ans += 1
                    if i >= 2:
                        a = ord(s[i - 2]) - 48
                        if (2 * a + b) % 4 == 0:
                            ans += i - 1
            elif d == 7:
                ans += cnt7[key7]
            elif d == 9:
                ans += cnt9[r9]

            cnt3[r3] += 1
            cnt9[r9] += 1
            cnt7[key7] += 1

        return ans

