class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        L = 4 * s

        # Map boundary points to positions on a circle of length L.
        pos = []
        for x, y in points:
            if y == 0:
                pos.append(x)                  # bottom: (0,0) -> (s,0)
            elif x == s:
                pos.append(s + y)              # right:  (s,0) -> (s,s)
            elif y == s:
                pos.append(3 * s - x)          # top:    (s,s) -> (0,s)
            else:  # x == 0
                pos.append(4 * s - y)          # left:   (0,s) -> (0,0)

        pos.sort()
        n = len(pos)
        a = pos + [p + L for p in pos]
        m = 2 * n

        def can(d: int) -> bool:
            # nxt[i] = first index after i with position at least a[i] + d
            nxt = [m] * (m + 1)
            j = 0
            for i in range(m):
                if j < i + 1:
                    j = i + 1
                limit = a[i] + d
                while j < m and a[j] < limit:
                    j += 1
                nxt[i] = j

            max_span = L - d
            jumps = k - 1
            for start in range(n):
                cur = start
                end = start + n
                for _ in range(jumps):
                    cur = nxt[cur]
                    if cur >= end:
                        break
                else:
                    # Also need the wrap-around gap to be at least d.
                    if a[cur] - a[start] <= max_span:
                        return True
            return False

        lo, hi = 0, L // k  # for k >= 4 this is <= side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

