                cnt += 1
            else:
                res = res * inv_fact[cnt] % MOD
                cnt = 1
        if m:
            res = res * inv_fact[cnt] % MOD
        key = tuple(sorted_uids)
        uid = uid_of.get(key)
        if uid is None:
            uid = len(uid_of)
            uid_of[key] = uid
