class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [''] * L
        forced = [False] * L

        # Apply T constraints
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    p = i + j
                    if forced[p]:
                        if word[p] != str2[j]:
                            return ""
                    else:
                        forced[p] = True
                        word[p] = str2[j]

        # Fill free positions with 'a'
        for p in range(L):
            if not forced[p]:
                word[p] = 'a'

        # Repair F constraints
        for i, c in enumerate(str1):
            if c == 'F':
                matches = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        matches = False
                        break
                if matches:
                    found = False
                    for j in range(i + m - 1, i - 1, -1):
                        if not forced[j]:
                            target = str2[j - i]
                            word[j] = 'b' if target == 'a' else 'a'
                            found = True
                            break
                    if not found:
                        return ""

        res = ''.join(word)

        # Final verification
        for i, c in enumerate(str1):
            sub = res[i:i + m]
            if c == 'T' and sub != str2:
                return ""
            if c == 'F' and sub == str2:
                return ""

        return res

