class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def bounce_cost(e: List[int]) -> int:
            # Minimum total bounces y_0..y_{n-2} with y_{i-1} + y_i >= e_i
            prev = 0
            total = 0
            for i in range(n - 1):
                y = e[i] - prev
                if y < 0:
                    y = 0
                total += y
                prev = y
            if prev < e[n - 1]:
                total += e[n - 1] - prev
            return total

        def feasible(k: int) -> bool:
            if k == 0:
                return True
            need = [(k + p - 1) // p for p in points]
            eA = [max(0, x - 1) for x in need]
            # Option A: no tail
            if n + 2 * bounce_cost(eA) <= m:
                return True
            # Option B: tail of length 1 covering cell n-2
            eB = eA[:]
            eB[n - 2] = max(0, need[n - 2] - 2)
            if n + 1 + 2 * bounce_cost(eB) <= m:
                return True
            return False

        lo = 0
        hi = max(points) * m + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

