class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def perim(x, y):
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2 * side + (side - x)
            # x == 0
            return 3 * side + (side - y)

        pts = sorted(((perim(x, y), x, y) for x, y in points))
        coords = [(x, y) for _, x, y in pts]
        n = len(coords)

        def feasible(d):
            for s in range(n):
                chosen = [coords[s]]
                for step in range(1, n):
                    idx = (s + step) % n
                    cx, cy = coords[idx]
                    ok = True
                    for (px, py) in chosen:
                        if abs(cx - px) + abs(cy - py) < d:
                            ok = False
                            break
                    if ok:
                        chosen.append((cx, cy))
                        if len(chosen) >= k:
                            return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

