            pi[i] = j

        full_next = pi[-1]  # state after a full occurrence of str2

        # Automaton states are 0 .. m-1: length of the longest prefix of str2
        # that is a suffix of the built string.
        go = [[0] * 26 for _ in range(m)]
        for s in range(m):
            for c in range(26):
                if c == p[s]:
                    ns = s + 1
                    if ns == m:
                        ns = full_next
                elif s == 0:
                    ns = 0
                else:
                    ns = go[pi[s - 1]][c]
                go[s][c] = ns

        # forbidden_end[e] is True iff an occurrence of str2 ending at e
        # would start at an 'F' position.
        forbidden_end = [False] * L
        for e in range(m - 1, L):
            start = e - m + 1
            if str1[start] == 'F':
                forbidden_end[e] = True

        # feasible[pos][s]: can positions pos .. L-1 be completed legally
        # when the current KMP suffix state is s?
        feasible = [bytearray(m) for _ in range(L + 1)]
        feasible[L] = bytearray(b"\x01" * m)

        for pos in range(L - 1, -1, -1):
            row = bytearray(m)
            nxt = feasible[pos + 1]
            fc = fixed[pos]

            if fc is not None:
                c = ord(fc) - 97
                bad_full = forbidden_end[pos] and c == last
                for s in range(m):
                    if bad_full and s == m - 1:
                        continue
                    ns = go[s][c]
                    if nxt[ns]:
                        row[s] = 1
            else:
                if forbidden_end[pos]:
                    for s in range(m):
                        gs = go[s]
                        if s == m - 1:
                            # Using `last` here would complete str2 at an F-start.
                            for c in range(26):
                                if c != last and nxt[gs[c]]:
                                    row[s] = 1
                                    break
                        else:
                            for c in range(26):
                                if nxt[gs[c]]:
                                    row[s] = 1
                                    break
                else:
                    for s in range(m):
                        gs = go[s]
                        for c in range(26):
                            if nxt[gs[c]]:
                                row[s] = 1
                                break

            feasible[pos] = row

        if not feasible[0][0]:
            return ""

        # Greedy lexicographically smallest construction using the DP table.
        ans = []
        s = 0
        for pos in range(L):
            if fixed[pos] is not None:
                candidates = (ord(fixed[pos]) - 97,)
            else:
                candidates = range(26)

            for c in candidates:
                if forbidden_end[pos] and s == m - 1 and c == last:
                    continue
                ns = go[s][c]
                if feasible[pos + 1][ns]:
                    ans.append(chr(97 + c))
                    s = ns
                    break

        return "".join(ans)

class Solution:
    def countSubstrings(self, s: str) -> int:
        answer = 0

        # Prefix digit-sum residues for divisibility by 3 and 9.
        prefix3 = prefix9 = 0
        count3 = [1, 0, 0]
        count9 = [1] + [0] * 8

        # Normalized prefix values modulo 7.
        prefix7 = 0
        inverse_power7 = 1
        count7 = [1] + [0] * 6

        for i, char in enumerate(s):
            digit = ord(char) - ord('0')

            prefix3 = (prefix3 + digit) % 3
            prefix9 = (prefix9 + digit) % 9

            if digit in (1, 2, 5):
                answer += i + 1
            elif digit in (3, 6):
                answer += count3[prefix3]
            elif digit == 9:
                answer += count9[prefix9]
            elif digit == 4:
                answer += 1  # The one-digit substring.
                if i >= 1 and int(s[i - 1:i + 1]) % 4 == 0:
                    answer += i  # All substrings of length at least two.
            elif digit == 8:
                answer += 1  # The one-digit substring.
                if i >= 1 and int(s[i - 1:i + 1]) % 8 == 0:
                    answer += 1
                if i >= 2 and int(s[i - 2:i + 1]) % 8 == 0:
                    answer += i - 1
            elif digit == 7:
                prefix7 = (prefix7 * 10 + digit) % 7
                inverse_power7 = (inverse_power7 * 5) % 7  # 10^-1 mod 7
                normalized = (prefix7 * inverse_power7) % 7
                answer += count7[normalized]
                count7[normalized] += 1

            count3[prefix3] += 1
            count9[prefix9] += 1

        return answer

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1

        # Zero means the character is not fixed by any 'T' window.
        fixed = bytearray(length)
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    value = ord(ch)
                    if fixed[pos] and fixed[pos] != value:
                        return ""
                    fixed[pos] = value

        # Active clauses are 'F' windows that still need a mismatch.
        active = bytearray(n)
        remaining = [0] * n
        offsets = [j for j, ch in enumerate(str2) if ch == 'a']

        for i, flag in enumerate(str1):
            if flag != 'F':
                continue

            candidates = 0
            already_different = False
            for j, ch in enumerate(str2):
                value = ord(ch)
                pos = i + j
                if fixed[pos]:
                    if fixed[pos] != value:
                        already_different = True
                        break
                elif value != ord('a'):
                    # An unfixed position will be 'a', so this already
                    # guarantees a mismatch.
                    already_different = True
                    break
                else:
                    candidates += 1

            if not already_different:
                if candidates == 0:
                    return ""
                active[i] = 1
                remaining[i] = candidates

        # Process positions from left to right to get the lexicographically
        # smallest result. Keep a position as 'a' unless doing so would leave
        # some active window with no other candidate.
        for pos in range(length):
            if fixed[pos]:
                continue

            must_change = False
            for j in offsets:
                start = pos - j
                if 0 <= start < n and active[start] and remaining[start] == 1:
                    must_change = True
                    break

            if must_change:
                fixed[pos] = ord('b')
                for j in offsets:
                    start = pos - j
                    if 0 <= start < n:
                        active[start] = 0
            else:
                for j in offsets:
                    start = pos - j
                    if 0 <= start < n and active[start]:
                        remaining[start] -= 1

        return bytes(value if value else ord('a') for value in fixed).decode()

