class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each boundary point to its position around the square.
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                pos = x
            elif x == side:
                pos = side + y
            elif y == side:
                pos = 3 * side - x
            else:  # x == 0
                pos = 4 * side - y
            positions.append(pos)

        positions.sort()
        n = len(positions)
        doubled = positions + [p + perimeter for p in positions]

        def feasible(distance: int) -> bool:
            # next_index[i] is the earliest position at least distance
            # after doubled[i].
            next_index = [2 * n] * (2 * n)
            j = 0
            for i in range(2 * n):
                j = max(j, i + 1)
                target = doubled[i] + distance
                while j < 2 * n and doubled[j] < target:
                    j += 1
                next_index[i] = j

            # Try each point as the first selected point. Greedily taking
            # the earliest possible next point leaves the most room.
            for start in range(n):
                current = start
                for _ in range(k - 1):
                    current = next_index[current]
                    if current >= start + n:
                        break
                else:
                    if doubled[current] - doubled[start] <= perimeter - distance:
                        return True

            return False

        # For k >= 4, the answer cannot exceed side: among k cyclic gaps
        # around a perimeter of length 4 * side, one gap is at most side.
        low, high = 0, side
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

