class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        low = 0
        high = max(points) * m  # Initial upper bound

        def is_feasible(target: int) -> bool:
            required = 0
            for p in points:
                required += (target + p - 1) // p  # Equivalent to ceil(target / p)
                if required > m:
                    return False
            return required <= m

        answer = 0
        while low <= high:
            mid = (low + high) // 2
            if is_feasible(mid):
                answer = mid
                low = mid + 1
            else:
                high = mid - 1
        return answer

import sys

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 2)  # Using 1-based indexing

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    ft = FenwickTree(n)
    # Initialize all positions to 1
    for i in range(1, n+1):
        ft.update(i, 1)

    result = [0] * n

    for i in range(n, 0, -1):
        pi = p[i-1]
        low = 1
        high = n
        pos = 0
        while low <= high:
            mid = (low + high) // 2
            s = ft.query(mid)
            if s < pi:
                low = mid + 1
            else:
                high = mid - 1
        pos = low
        result[pos - 1] = i
        ft.update(pos, -1)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_length = n + m - 1
        word = [None] * total_length

        # Step 1: Process 'T' constraints
        possible = True
        for j in range(n):
            if str1[j] == 'T':
                for k in range(m):
                    pos = j + k
                    if pos >= total_length:
                        possible = False
                        break
                    expected_char = str2[k]
                    if word[pos] is not None:
                        if word[pos] != expected_char:
                            possible = False
                            break
                    else:
                        word[pos] = expected_char
                if not possible:
                    break
        if not possible:
            return ""

        # Step 2: Collect F_list (F positions where current fixed characters match str2)
        F_list = []
        for j in range(n):
            if str1[j] == 'F':
                valid = True
                for k in range(m):
                    pos = j + k
                    if pos >= total_length:
                        valid = False
                        break
                    if word[pos] is not None and word[pos] != str2[k]:
                        valid = False
                        break
                if valid:
                    F_list.append(j)

        # Collect candidate positions (unfixed positions in windows of F_list)
        candidates = []
        for j in F_list:
            for k in range(m):
                pos = j + k
                if pos < total_length and word[pos] is None:
                    candidates.append(pos)
        # Remove duplicates and sort
        candidates = sorted(list(set(candidates)))

        remaining_F = F_list.copy()

        # Process each candidate position to break F constraints
        for k in candidates:
            # Find all F j that include k in their window
            affected_j = []
            for j in remaining_F:
                if j <= k < j + m:
                    affected_j.append(j)
            if not affected_j:
                continue

            # Collect required characters for these j's
            required_chars = set()
            for j in affected_j:
                idx_in_str2 = k - j
                if 0 <= idx_in_str2 < m:
                    required_chars.add(str2[idx_in_str2])

            # Find the smallest character not in required_chars
            found = False
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c not in required_chars:
                    word[k] = c
                    # Remove affected_j from remaining_F
                    for j in affected_j:
                        if j in remaining_F:
                            remaining_F.remove(j)
                    found = True
                    break
            if not found:
                return ""
            if not remaining_F:
                break

        if remaining_F:
            return ""

        # Fill remaining None with 'a's
        for i in range(total_length):
            if word[i] is None:
                word[i] = 'a'

        return ''.join(word)

