from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_s(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 3 * side - x
            else:  # x == 0
                return 4 * side - y

        # Compute s for each point and sort them
        s_list = [get_s(x, y) for x, y in points]
        s_list.sort()
        n = len(s_list)
        if n < k:
            return 0  # Not possible, but according to constraints k <= points.length

        # Binary search between low and high
        low = 0
        high = 2 * side  # Maximum possible Manhattan distance is 2*side (between opposite corners)
        best = 0

        while low <= high:
            mid = (low + high) // 2
            if self.is_possible(mid, s_list, side, k):
                best = mid
                low = mid + 1
            else:
                high = mid - 1
        return best

    def is_possible(self, d: int, sorted_s: List[int], side: int, k: int) -> bool:
        n = len(sorted_s)
        if n < k:
            return False
        m = 4 * side
        extended = sorted_s + [x + m for x in sorted_s]

        for start_idx in range(n):
            current = start_idx  # position in extended list
            count = 1
            for _ in range(k - 1):
                target = extended[current] + d
                j = bisect.bisect_left(extended, target)
                if j >= 2 * n:
                    break  # can't find enough points
                actual_j = j % n
                if actual_j == current % n:
                    break  # can't select the same point again
                current = j
                count += 1
                if count == k:
                    return True
            if count == k:
                return True
        return False

