class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        def feasible(target: int) -> bool:
            moves = 0
            previous_visits = 0

            for i, value in enumerate(points):
                required_visits = (target + value - 1) // value
                needed = required_visits - previous_visits

                if needed > 0:
                    # Enter i once, then bounce to a neighbor and back
                    # for each additional required visit.
                    moves += 2 * needed - 1

                    # These bounces also visit i + 1.
                    previous_visits = needed - 1
                else:
                    # Cross this already-satisfied position to continue.
                    # If it is the last position, we can stop immediately.
                    if i < n - 1:
                        moves += 1
                    previous_visits = 0

                if moves > m:
                    return False

            return True

        low = 0
        # A position can be visited at most ceil(m / 2) times.
        high = min(points) * ((m + 1) // 2)

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

