                required = (target + value - 1) // value
                missing = required - carried_visits

                if missing > 0:
                    # Enter i once, then make missing - 1 round trips.
                    # At the last position, round trips use the left neighbor.
                    moves += 2 * missing - 1
                    carried_visits = missing - 1
                else:
                    # This position already has enough visits. If it is the
                    # last one, stop without moving onto it again.
                    if i == n - 1:
                        return True

                    moves += 1
                    carried_visits = 0

                if moves > m:
                    return False

            return True

        # Consecutive visits to one position require at least two moves,
        # so no position can be visited more than ceil(m / 2) times.
        low = 0
        high = min(points) * ((m + 1) // 2)

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

