class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        # Every position must be visited to obtain a positive minimum.
        if m < n:
            return 0

        def feasible(target: int) -> bool:
            moves = 0
            carried_visits = 0

            for i, value in enumerate(points):
                required_visits = (target + value - 1) // value
                extra_visits = required_visits - carried_visits

                if extra_visits > 0:
                    # Enter this position, then bounce extra_visits - 1 times.
                    moves += 2 * extra_visits - 1
                    carried_visits = extra_visits - 1
                else:
                    # This position already has enough visits. Move through it
                    # only if there are still positions ahead to process.
                    if i < n - 1:
                        moves += 1
                    carried_visits = 0

                if moves > m:
                    return False

            return True

        # Consecutive visits to a position require at least two moves.
        low = 0
        high = min(points) * ((m + 1) // 2)

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = str2.encode()

        word = bytearray(b'a' * length)
        fixed = bytearray(length)
        fixed_block = b'\x01' * m

        # Place all required occurrences, checking their overlaps.
        previous_end = 0
        for i, condition in enumerate(str1):
            if condition != 'T':
                continue

            if i < previous_end:
                overlap = previous_end - i
                if word[i:previous_end] != pattern[:overlap]:
                    return ""

            word[i:i + m] = pattern
            fixed[i:i + m] = fixed_block
            previous_end = i + m

        # Break forbidden occurrences as far to the right as possible.
        # All positions not forced by a 'T' initially contain 'a'.
        for i, condition in enumerate(str1):
            if condition != 'F' or word[i:i + m] != pattern:
                continue

            j = i + m - 1
            while j >= i and fixed[j]:
                j -= 1

            if j < i:
                return ""

            word[j] = ord('b')
            fixed[j] = 1

        return word.decode()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        word = ['a'] * length
        fixed = [False] * length
        pattern = list(str2)

        # Every 'T' forces all characters in its window.
        for i, requirement in enumerate(str1):
            if requirement == 'T':
                for j, char in enumerate(str2):
                    pos = i + j
                    if fixed[pos] and word[pos] != char:
                        return ""
                    word[pos] = char
                    fixed[pos] = True

        # Unforced characters initially contain 'a'. If an 'F' window
        # matches, change its rightmost available character to 'b'.
        for i, requirement in enumerate(str1):
            if requirement == 'F' and word[i:i + m] == pattern:
                pos = i + m - 1
                while pos >= i and fixed[pos]:
                    pos -= 1

                if pos < i:
                    return ""

                word[pos] = 'b'
                fixed[pos] = True

        # Verify every constraint on the completed string.
        result = ''.join(word)
        for i, requirement in enumerate(str1):
            matches = result[i:i + m] == str2
            if matches != (requirement == 'T'):
                return ""

        return result

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = [ord(c) - ord('a') for c in str2]

        # Every 'T' window fixes all of its characters.
        fixed = [-1] * length
        for start, requirement in enumerate(str1):
            if requirement == 'T':
                for offset, char in enumerate(pattern):
                    pos = start + offset
                    if fixed[pos] != -1 and fixed[pos] != char:
                        return ""
                    fixed[pos] = char

        # KMP prefix function.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j

        # States are matched-prefix lengths 0 through m - 1.
        # After a complete match, continue from its longest proper border.
        transitions = []
        for state in range(m):
            if state == 0:
                row = [0] * 26
            else:
                row = transitions[pi[state - 1]].copy()

            row[pattern[state]] = (
                state + 1 if state + 1 < m else pi[m - 1]
            )
            transitions.append(row)

        bits = [1 << char for char in pattern]
        inverse_bits = [~bit for bit in bits]
        all_letters = (1 << 26) - 1
        last_char = pattern[-1]
        border = pi[-1]

        # feasible[pos][state]: can the suffix starting at pos be completed
        # when the current KMP state is state?
        feasible = [None] * (length + 1)
        feasible[length] = bytearray([1]) * m

        for pos in range(length - 1, -1, -1):
            following = feasible[pos + 1]
            current = bytearray(m)

            start = pos - m + 1
            forbid_match = start >= 0 and str1[start] == 'F'
            char = fixed[pos]

            if char != -1:
                for state in range(m):
                    if (
                        forbid_match
                        and state == m - 1
                        and char == last_char
                    ):
                        continue
                    current[state] = following[transitions[state][char]]
            else:
                # masks[state] contains all characters that permit a valid
                # completion. KMP failure links let us compute each mask in
                # O(1), rather than checking all 26 characters per state.
                masks = [0] * m

                for state in range(m):
                    if state == 0:
                        mask = all_letters if following[0] else 0
                    else:
                        mask = masks[pi[state - 1]]

                    # The expected character overrides the failure transition.
                    mask &= inverse_bits[state]

                    if state < m - 1:
                        if following[state + 1]:
                            mask |= bits[state]
                    elif not forbid_match and following[border]:
                        mask |= bits[state]

                    masks[state] = mask
                    current[state] = bool(mask)

            feasible[pos] = current

        if not feasible[0][0]:
            return ""

        # Choose the smallest character that preserves suffix feasibility.
        answer = []
        state = 0

        for pos in range(length):
            start = pos - m + 1
            forbid_match = start >= 0 and str1[start] == 'F'

            if fixed[pos] != -1:
                char = fixed[pos]
            else:
                for char in range(26):
                    if (
                        forbid_match
                        and state == m - 1
                        and char == last_char
                    ):
                        continue

                    next_state = transitions[state][char]
                    if feasible[pos + 1][next_state]:
                        break

            answer.append(chr(ord('a') + char))
            state = transitions[state][char]

        return "".join(answer)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = [ord(c) - ord('a') for c in str2]

        # KMP prefix function.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j

        # State q means the current suffix matches str2[:q].
        # After a complete match, fall back to pi[m - 1].
        transition = [[0] * 26 for _ in range(m)]
        for q in range(m):
            for c in range(26):
                if c == pattern[q]:
                    transition[q][c] = q + 1 if q + 1 < m else pi[-1]
                elif q:
                    transition[q][c] = transition[pi[q - 1]][c]

        # A substring starting at i finishes at position i + m - 1.
        # -1: unrestricted, 0: must not match, 1: must match.
        required = [-1] * (m - 1) + [
            1 if c == 'T' else 0 for c in str1
        ]

        # possible[pos][q]: can we finish the word starting at pos
        # when the KMP state before this position is q?
        possible = [None] * (length + 1)
        possible[length] = bytearray([1]) * m

        all_letters = (1 << 26) - 1
        bits = [1 << c for c in pattern]
        clear_bits = [all_letters ^ bit for bit in bits]
        letter_masks = [0] * m

        for pos in range(length - 1, -1, -1):
            following = possible[pos + 1]
            row = bytearray(m)

            if required[pos] == 1:
                # Only this state and str2's final character can
                # produce a complete match at this position.
                row[m - 1] = following[pi[-1]]
            else:
                base_mask = all_letters if following[0] else 0

                for q in range(m):
                    # All characters except pattern[q] follow the
                    # same transitions as the KMP fallback state.
                    inherited = (
                        base_mask if q == 0
                        else letter_masks[pi[q - 1]]
                    )
                    mask = inherited & clear_bits[q]

                    if q + 1 < m:
                        can_advance = following[q + 1]
                    else:
                        can_advance = (
                            required[pos] != 0 and following[pi[-1]]
                        )

                    if can_advance:
                        mask |= bits[q]

                    letter_masks[q] = mask
                    row[q] = bool(mask)

            possible[pos] = row

        if not possible[0][0]:
            return ""

        # Greedily select the smallest character that preserves
        # feasibility of the remaining suffix.
        answer = []
        state = 0

        for pos in range(length):
            need = required[pos]
            following = possible[pos + 1]

            for c in range(26):
                completes_match = (
                    state == m - 1 and c == pattern[state]
                )

                if need == 1 and not completes_match:
                    continue
                if need == 0 and completes_match:
                    continue

                next_state = transition[state][c]
                if following[next_state]:
                    answer.append(chr(ord('a') + c))
                    state = next_state
                    break

        # Time: O((n + m) * m + 26 * (n + m)).
        # Space: O((n + m) * m).
        return "".join(answer)

class Solution:
    def countSubstrings(self, s: str) -> int:
        # dp[d][r]: number of substrings ending at the previous position
        # whose numeric value has remainder r modulo d.
        dp = [[0] * d for d in range(10)]
        answer = 0

        for char in s:
            digit = ord(char) - ord('0')

            for divisor in range(1, 10):
                current = [0] * divisor

                # Start a new one-digit substring.
                current[digit % divisor] = 1

                # Extend every substring ending at the previous position.
                for remainder, count in enumerate(dp[divisor]):
                    new_remainder = (remainder * 10 + digit) % divisor
                    current[new_remainder] += count

                dp[divisor] = current

            if digit != 0:
                answer += dp[digit][0]

        return answer

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        from collections import deque

        n, m = len(str1), len(str2)
        length = n + m - 1
        word = [""] * length
        pattern = list(str2)

        # Every T window forces its characters.
        for i, requirement in enumerate(str1):
            if requirement == "T":
                for j, char in enumerate(str2):
                    position = i + j
                    if word[position] and word[position] != char:
                        return ""
                    word[position] = char

        free = [not char for char in word]

        # Use the smallest character wherever no T window forces a value.
        for i in range(length):
            if free[i]:
                word[i] = "a"

        # Available, still-unmodified positions in the current window.
        available = deque(i for i in range(m - 1) if free[i])

        for i, requirement in enumerate(str1):
            while available and available[0] < i:
                available.popleft()

            right = i + m - 1
            if free[right]:
                available.append(right)

            if requirement == "F" and word[i:i + m] == pattern:
                if not available:
                    return ""

                # Change the rightmost available 'a' to 'b', preserving
                # the longest possible lexicographically minimal prefix.
                position = available.pop()
                word[position] = "b"

        return "".join(word)

