class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        # Map boundary points to clockwise positions on the perimeter.
        positions = []
        for x, y in points:
            if y == 0:
                positions.append(x)
            elif x == side:
                positions.append(side + y)
            elif y == side:
                positions.append(3 * side - x)
            else:
                positions.append(perimeter - y)

        positions.sort()
        n = len(positions)
        extended = positions + [p + perimeter for p in positions]
        size = 2 * n

        def feasible(distance: int) -> bool:
            # next_index[i] is the earliest point at least distance
            # clockwise from point i.
            next_index = [size] * size
            j = 0
            for i in range(size):
                target = extended[i] + distance
                while j < size and extended[j] < target:
                    j += 1
                next_index[i] = j

            # Try every point as the first selected point. Greedily choosing
            # the earliest possible successor leaves the most closing space.
            for start in range(n):
                last_allowed = extended[start] + perimeter - distance
                current = start

                for _ in range(k - 1):
                    current = next_index[current]
                    if current == size or extended[current] > last_allowed:
                        break
                else:
                    return True

            return False

        # Some consecutive selected pair has perimeter gap <= perimeter / k,
        # and its Manhattan distance cannot exceed that gap. Since k >= 4,
        # the answer is at most side.
        #
        # For distances <= side, the Manhattan-distance constraint is
        # equivalent to requiring every circular perimeter gap to be at
        # least that distance.
        low, high = 0, perimeter // k
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

