            else:
                positions.append(perimeter - y)

        positions.sort()
        n = len(positions)
        positions += [p + perimeter for p in positions]
        total = 2 * n

        def feasible(distance: int) -> bool:
            # next_index[i] is the earliest point at least distance
            # clockwise from point i.
            next_index = [total] * (total + 1)
            j = 0
            for i in range(total):
                j = max(j, i + 1)
                target = positions[i] + distance
                while j < total and positions[j] < target:
                    j += 1
                next_index[i] = j

            # Fix the first point and greedily choose the earliest possible
            # subsequent points. This leaves maximum room for the closing gap.
            for start in range(n):
                current = start
                end = start + n

                for _ in range(k - 1):
                    current = next_index[current]
                    if current >= end:
                        break

                if (
                    current < end
                    and positions[current] - positions[start]
                    <= perimeter - distance
                ):
                    return True

            return False

        # Manhattan distance never exceeds the shorter boundary distance.
        # Thus the optimum is at most perimeter // k, which is <= side
        # because k >= 4. For thresholds <= side, checking boundary
        # distances is equivalent to checking Manhattan distances:
        # opposite edges are already at least side apart, while points
        # on the same or adjacent edges have equal relevant distances.
        low, high = 0, perimeter // k

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

