class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        def feasible(target: int) -> bool:
            moves = 0
            carried_visits = 0

            for i, value in enumerate(points):
                required_visits = (target + value - 1) // value
                extra_visits = required_visits - carried_visits

                if extra_visits > 0:
                    # Enter this index, then bounce with i+1 to obtain extra visits.
                    moves += 2 * extra_visits - 1
                    carried_visits = extra_visits - 1
                else:
                    # Already satisfied; only step forward if more indices remain.
                    if i < n - 1:
                        moves += 1
                    carried_visits = 0

                if moves > m:
                    return False

            return True

        low = 0
        high = min(points) * ((m + 1) // 2)

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

