        fixed = bytearray(length)
        pattern = list(str2)

        # First enforce every required occurrence of str2.
        for i, condition in enumerate(str1):
            if condition == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    if fixed[pos] and word[pos] != ch:
                        return ""
                    word[pos] = ch
                    fixed[pos] = 1

        # Free positions initially contain 'a'. For each forbidden occurrence,
        # change its rightmost free position to 'b', preserving the smallest prefix.
        for i, condition in enumerate(str1):
            if condition == 'F' and word[i:i + m] == pattern:
                pos = i + m - 1
                while pos >= i and fixed[pos]:
                    pos -= 1

                if pos < i:
                    return ""

                word[pos] = 'b'
                fixed[pos] = 1

        return ''.join(word)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # Positions forced by 'T' constraints.
        fixed = [None] * L
        for i, t in enumerate(str1):
            if t == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    if fixed[pos] is not None and fixed[pos] != ch:
                        return ""
                    fixed[pos] = ch

        p = [ord(ch) - 97 for ch in str2]
        last = p[-1]

        # KMP prefix function for str2.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j

        full_next = pi[-1]  # state after a full occurrence of str2

        # Automaton states are 0 .. m-1: length of the longest prefix of str2
        # that is a suffix of the built string.
        go = [[0] * 26 for _ in range(m)]
        for s in range(m):
            for c in range(26):
                if c == p[s]:
                    ns = s + 1
                    if ns == m:
                        ns = full_next
                elif s == 0:
                    ns = 0
                else:
                    ns = go[pi[s - 1]][c]
                go[s][c] = ns

        # forbidden_end[e] is True iff an occurrence of str2 ending at e
        # would start at an 'F' position.
        forbidden_end = [False] * L
        for e in range(m - 1, L):
            start = e - m + 1
            if str1[start] == 'F':
                forbidden_end[e] = True

        # feasible[pos][s]: can positions pos .. L-1 be completed legally
        # when the current KMP suffix state is s?
        feasible = [bytearray(m) for _ in range(L + 1)]
        feasible[L] = bytearray(b"\x01" * m)

        for pos in range(L - 1, -1, -1):
            row = bytearray(m)
            nxt = feasible[pos + 1]
            fc = fixed[pos]

            if fc is not None:
                c = ord(fc) - 97
                bad_full = forbidden_end[pos] and c == last
                for s in range(m):
                    if bad_full and s == m - 1:
                        continue
                    ns = go[s][c]
                    if nxt[ns]:
                        row[s] = 1
            else:
                if forbidden_end[pos]:
                    for s in range(m):
                        gs = go[s]
                        if s == m - 1:
                            # Using `last` here would complete str2 at an F-start.
                            for c in range(26):
                                if c != last and nxt[gs[c]]:
                                    row[s] = 1
                                    break
                        else:
                            for c in range(26):
                                if nxt[gs[c]]:
                                    row[s] = 1
                                    break
                else:
                    for s in range(m):
                        gs = go[s]
                        for c in range(26):
                            if nxt[gs[c]]:
                                row[s] = 1
                                break

            feasible[pos] = row

        if not feasible[0][0]:
            return ""

        # Greedy lexicographically smallest construction using the DP table.
        ans = []
        s = 0
        for pos in range(L):
            if fixed[pos] is not None:
                candidates = (ord(fixed[pos]) - 97,)
            else:
                candidates = range(26)

            for c in candidates:
                if forbidden_end[pos] and s == m - 1 and c == last:
                    continue
                ns = go[s][c]
                if feasible[pos + 1][ns]:
                    ans.append(chr(97 + c))
                    s = ns
                    break

        return "".join(ans)

class Solution:
    def countSubstrings(self, s: str) -> int:
        ans = 0

        cnt3 = [1, 0, 0]
        cnt9 = [1] + [0] * 8
        cnt7 = [1] + [0] * 6

        r3 = r9 = 0
        p7 = 0          # prefix value mod 7
        inv10_7 = 1     # 10^{-prefix_len} mod 7

        for i, ch in enumerate(s):
            d = ord(ch) - 48

            r3 = (r3 + d) % 3
            r9 = (r9 + d) % 9

            p7 = (p7 * 3 + d) % 7        # 10 == 3 (mod 7)
            inv10_7 = (inv10_7 * 5) % 7  # 5 == 10^{-1} (mod 7)
            key7 = p7 * inv10_7 % 7

            if d == 1 or d == 2 or d == 5:
                ans += i + 1
            elif d == 3 or d == 6:
                ans += cnt3[r3]
            elif d == 4:
                ans += 1
                if i and ((ord(s[i - 1]) - 48) & 1) == 0:
                    ans += i
            elif d == 8:
                ans += 1
                if i:
                    b = ord(s[i - 1]) - 48
                    if b % 4 == 0:
                        ans += 1
                    if i >= 2:
                        a = ord(s[i - 2]) - 48
                        if (2 * a + b) % 4 == 0:
                            ans += i - 1
            elif d == 7:
                ans += cnt7[key7]
            elif d == 9:
                ans += cnt9[r9]

            cnt3[r3] += 1
            cnt9[r9] += 1
            cnt7[key7] += 1

        return ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        # dp[d][r]: number of substrings ending at the previous position
        # whose value has remainder r modulo d.
        dp = [[]] + [[0] * d for d in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                current = [0] * d

                # Extend all substrings ending at the previous position.
                for remainder, count in enumerate(dp[d]):
                    current[(remainder * 10 + digit) % d] += count

                # Include the single-digit substring.
                current[digit % d] += 1
                dp[d] = current

            if digit != 0:
                answer += dp[digit][0]

        return answer

