class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        # Map boundary points to positions along the perimeter (counterclockwise).
        positions = []
        for x, y in points:
            if x == 0:
                positions.append(y)
            elif y == side:
                positions.append(side + x)
            elif x == side:
                positions.append(3 * side - y)
            else:
                positions.append(perimeter - x)

        positions.sort()
        n = len(positions)
        extended = positions + [p + perimeter for p in positions]
        m = len(extended)
        extended.append(3 * perimeter)  # Sentinel for "no available point".

        def feasible(distance: int) -> bool:
            # jump[i] = index of the first point at least `distance` after point i.
            jump = [m] * (m + 1)
            j = 0
            for i in range(m):
                while j < m and extended[j] - extended[i] < distance:
                    j += 1
                jump[i] = j

            # From every possible starting point, perform k-1 greedy selections
            # using binary lifting.
            endpoints = list(range(n))
            steps = k - 1
            while steps:
                if steps & 1:
                    endpoints = [jump[index] for index in endpoints]
                steps >>= 1
                if steps:
                    jump = [jump[index] for index in jump]

            # The last chosen point must also be at least `distance` away from
            # the first one across the wraparound gap.
            for start, end in enumerate(endpoints):
                if extended[end] <= positions[start] + perimeter - distance:
                    return True
            return False

        # Any k points on the perimeter have some consecutive arc <= perimeter // k,
        # and Manhattan distance <= arc distance, so the answer <= perimeter // k <= side.
        # For thresholds <= side, "Manhattan >= d" equals "arc >= d" on a square boundary.
        low, high = 0, perimeter // k
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

