class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def check(target: int) -> bool:
            moves = 0
            carry = 0  # visits already granted to current index from previous back-and-forth
            for i in range(n):
                need = (target + points[i] - 1) // points[i]  # visits needed at i
                need -= carry
                if i == n - 1:
                    if need <= 0:
                        # already satisfied by earlier bounce; no extra move needed
                        pass
                    else:
                        # one move to arrive (if carry==0 then need includes that), plus bounces
                        moves += 2 * need - 1
                else:
                    if need <= 0:
                        # must still step onto i to move forward (once), unless carry covers it;
                        # the step forward from i-1 to i is already counted in the bounce when carry>0?
                        # Handle: we step onto i (1 move) only if carry == 0.
                        # Actually carry>0 means we were already at i via a bounce, so moving forward costs 1.
                        moves += 1
                        carry = 0
                    else:
                        # first visit (arrive): 1 move; each additional visit requires a bounce to i+1 and back (2 moves)
                        # bounce gives i+1 one visit each.
                        moves += 1 + 2 * (need - 1)
                        carry = need - 1
                if moves > m:
                    return False
            return moves <= m

        lo, hi = 0, 10**15
        # Fix the counting: the "arrive" move for index i when carry>0 was already included
        # in the bounce cost of i-1. Re-implement cleanly below.
        def check2(target: int) -> bool:
            moves = 0
            carry = 0
            for i in range(n):
                need = (target + points[i] - 1) // points[i] - carry
                if i == n - 1:
                    if need > 0:
                        if carry == 0:
                            moves += 1
                            need -= 1
                        moves += 2 * need
                    # if need <= 0 and carry > 0, we've already been there
                    if need <= 0 and carry == 0:
                        pass  # target<=0 case only; nothing needed
                else:
                    if carry == 0:
                        moves += 1  # step onto i
                        need -= 1
                    if need > 0:
                        moves += 2 * need
                        carry = need
                    else:
                        carry = 0
                if moves > m:
                    return False
            return moves <= m

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check2(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
