class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def pos(x, y):
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2 * side + (side - x)
            return 3 * side + (side - y)
        P = sorted(pos(x, y) for x, y in points)
        n = len(P)
        per = 4 * side
        ext = P + [p + per for p in P]
        m = 2 * n

        def feasible(d):
            # nxt[i]: smallest j>i with ext[j]-ext[i] >= d
            LOG = max(1, (k - 1).bit_length())
            nxt = [m] * (m + 1)
            j = 0
            for i in range(m):
                if j < i + 1:
                    j = i + 1
                while j < m and ext[j] - ext[i] < d:
                    j += 1
                nxt[i] = j
            up = [nxt]
            for _ in range(LOG):
                prev = up[-1]
                up.append([prev[prev[i]] if prev[i] < m else m for i in range(m + 1)])
            steps = k - 1
            for s in range(n):
                cur = s
                t = steps
                b = 0
                ok = True
                while t:
                    if t & 1:
                        cur = up[b][cur]
                        if cur >= m:
                            ok = False
                            break
                    t >>= 1
                    b += 1
                if ok and ext[cur] - ext[s] <= per - d:
                    return True
            return False

        lo, hi = 1, per // k
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

