                        moves += 1
                        carry = 0
                    else:
                        # arrive once (1 move), then (need-1) bounces each costing 2 moves,
                        # which visit index i+1 (need-1) times
                        moves += 1 + 2 * (need - 1)
                        carry = need - 1
