        lo, hi = 0, max(points) * m
        # Make hi a valid upper bound (minimum could be up to roughly min over ... but this is safe)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
