class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side
        pos = []
        for x, y in points:
            if y == 0:
                p = x
            elif x == side:
                p = side + y
            elif y == side:
                p = 2 * side + (side - x)
            else:
                p = 3 * side + (side - y)
            pos.append(p)
        pos.sort()
        n = len(pos)
        pos2 = pos + [p + L for p in pos]
        m = 2 * n
        steps = k - 1

        def check(D):
            nxt = [0] * (m + 1)
            for i in range(m):
                nxt[i] = bisect_left(pos2, pos2[i] + D)
            nxt[m] = m
            # binary lifting
            cur = list(range(m + 1))
            table = nxt
            s = steps
            while s:
                if s & 1:
                    cur = [table[c] for c in cur]
                s >>= 1
                if s:
                    table = [table[t] for t in table]
            limit = L - D
            for i in range(n):
                j = cur[i]
                if j < m and pos2[j] - pos2[i] <= limit:
                    return True
            return False

        lo, hi = 1, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
