class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        pos = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == S:
                t = S + y
            elif y == S:
                t = 3 * S - x
            else:
                t = 4 * S - y
            pos.append(t)
        pos.sort()
        n = len(pos)
        L = 4 * S
        pos2 = pos + [p + L for p in pos]
        n2 = 2 * n

        def feasible(d):
            # nxt[i] = first index j with pos2[j] >= pos2[i] + d (n2 acts as sentinel)
            nxt = [bisect_left(pos2, p + d) for p in pos2]
            # choose reference r minimizing window size nxt[r]-r
            fs = [nxt[r] - r for r in range(n)]
            best_f = min(fs)
            r = fs.index(best_f)
            end = min(nxt[r], r + n)
            for s in range(r, end):
                s0 = s if s < n else s - n
                lim = s0 + n
                cur = s0
                ok = True
                for _ in range(k):
                    cur = nxt[cur]
                    if cur > lim:
                        ok = False
                        break
                if ok:
                    return True
            return False

        lo, hi = 1, min(S, L // k)
        if hi < 1:
            hi = 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

