        n = len(points)
        # Map each boundary point to a 1D position along the perimeter (counterclockwise from (0,0))
        P = []
        for x, y in points:
            if y == 0:
                P.append(x)
            elif x == side:
                P.append(side + y)
            elif y == side:
                P.append(3 * side - x)
            else:
                P.append(4 * side - y)
        P.sort()
        total = 4 * side
        N = 2 * n
        P2 = P + [p + total for p in P]
        P2.append(1 << 62)  # sentinel

        def feasible(d):
            # nxt[i] = smallest index j with P2[j] >= P2[i] + d  (N as sentinel)
            nxt = [N] * (N + 1)
            j = 0
            for i in range(n):
                t = P[i] + d
                while P2[j] < t:
                    j += 1
                nxt[i] = j
            for i in range(n, N):
                v = nxt[i - n] + n
                if v < N:
                    nxt[i] = v
            # Only starts within [P[0], P[0] + d) need to be tried
            m = bisect_left(P, P[0] + d)
            cur = list(range(m))
            for _ in range(k):
                cur = [nxt[c] for c in cur]
            for s in range(m):
                if cur[s] <= s + n:
                    return True
            return False

        lo, hi = 1, total // k
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

