        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        # Z-function of str2
        z = [0] * m
        z[0] = m
        l = r = 0
        for k in range(1, m):
            if k < r:
                z[k] = min(r - k, z[k - l])
            while k + z[k] < m and str2[z[k]] == str2[k + z[k]]:
                z[k] += 1
            if k + z[k] > r:
                l, r = k, k + z[k]

        T = [i for i in range(n) if str1[i] == 'T']
        for a, b in zip(T, T[1:]):
            d = b - a
            if d < m and z[d] < m - d:
                return ""

        word = ['a'] * L
        fixed = [False] * L
        cntT = len(T)
        for idx, t in enumerate(T):
            end = t + m
            if idx + 1 < cntT and T[idx + 1] < end:
                end = T[idx + 1]
            word[t:end] = list(str2[:end - t])
            fixed[t:end] = [True] * (end - t)

        lastFree = [-1] * L
        last = -1
        for x in range(L):
            if not fixed[x]:
                last = x
            lastFree[x] = last

        for i in range(n):
            if str1[i] == 'F':
                if ''.join(word[i:i + m]) == str2:
                    p = lastFree[i + m - 1]
                    if p < i:
                        return ""
                    word[p] = 'b'

        return ''.join(word)

