class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = str2.encode()

        word = bytearray(b'a' * length)
        fixed = bytearray(length)

        # Every 'T' forces an entire copy of str2.
        for i, requirement in enumerate(str1):
            if requirement == 'T':
                for j, char in enumerate(pattern):
                    pos = i + j
                    if fixed[pos] and word[pos] != char:
                        return ""
                    word[pos] = char
                    fixed[pos] = 1

        # Unforced positions initially contain the smallest letter, 'a'.
        # Break forbidden matches as far to the right as possible.
        for i, requirement in enumerate(str1):
            if requirement == 'F' and word[i:i + m] == pattern:
                pos = i + m - 1
                while pos >= i and fixed[pos]:
                    pos -= 1

                if pos < i:
                    return ""

                word[pos] = ord('b')
                fixed[pos] = 1

        return word.decode()

