def main():
    data = sys.stdin.buffer.read().split()
    n, m = map(int, data[:2])
    s = data[2]

    # Positions at which each character occurs in S.
    char_masks = {}
    for i, c in enumerate(s):
        char_masks[c] = char_masks.get(c, 0) | (1 << i)

    size = 1 << n
    absent = 26 - len(char_masks)

    # A state encodes consecutive differences of the LCS DP row:
    # bit i = LCS(S[:i+1], T) - LCS(S[:i], T).
    # Appending a character updates this row using bit operations.
    transitions = []
    for state in range(size):
        counts = {state: absent} if absent else {}
        shifted = (state << 1) | 1
        for mask in char_masks.values():
            x = state | mask
            nxt = x & ~(x - shifted)
            counts[nxt] = counts.get(nxt, 0) + 1
        transitions.append(list(counts.items()))

    dp = [0] * size
    dp[0] = 1

    for _ in range(m):
        new_dp = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for nxt, multiplicity in transitions[state]:
                    new_dp[nxt] = (
                        new_dp[nxt] + ways * multiplicity
                    ) % MOD
        dp = new_dp

    # Summing the row differences gives the final LCS length.
    answer = [0] * (n + 1)
    for state, ways in enumerate(dp):
        k = bin(state).count("1")
        answer[k] = (answer[k] + ways) % MOD

    print(*answer)


