class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        m = len(str2)
        length = len(str1) + m - 1

        # KMP prefix function.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # transition[state][character] is the new matched-prefix length.
        # A result of m means that a complete occurrence has just ended.
        transition = []
        for state in range(m):
            if state == 0:
                row = [0] * 26
            else:
                row = transition[pi[state - 1]].copy()
            row[ord(str2[state]) - ord('a')] = state + 1
            transition.append(row)

        fallback = pi[-1]

        # incoming[target] contains every state from which some character
        # reaches target without completing an occurrence.
        incoming = [0] * m
        for state, row in enumerate(transition):
            state_bit = 1 << state
            for target in row:
                if target < m:
                    incoming[target] |= state_bit

        # The condition for a window starting at i is checked when its
        # final character, at i + m - 1, is appended.
        required_match = [False] * (m - 1)
        required_match.extend(ch == 'T' for ch in str1)

        all_states = (1 << m) - 1
        accepting_state_bit = 1 << (m - 1)
        fallback_bit = 1 << fallback

        # good[pos] is a bitset of KMP states from which positions
        # pos..length-1 can be completed validly.
        good = [0] * (length + 1)
        good[length] = all_states

        # Every non-matching position uses the same reverse transition.
        reverse_cache = {all_states: all_states}

        for pos in range(length - 1, -1, -1):
            next_good = good[pos + 1]

            if required_match[pos]:
                if not (next_good & fallback_bit):
                    return ""
                good[pos] = accepting_state_bit
            else:
                current_good = reverse_cache.get(next_good)

                if current_good is None:
                    current_good = 0
                    remaining = next_good

                    while remaining:
                        bit = remaining & -remaining
                        target = bit.bit_length() - 1
                        current_good |= incoming[target]

                        if current_good == all_states:
                            break
                        remaining -= bit

                    reverse_cache[next_good] = current_good

                if current_good == 0:
                    return ""
                good[pos] = current_good

        if not (good[0] & 1):
            return ""

        # Choose the smallest character that still permits a valid suffix.
        answer = []
        state = 0

        for pos in range(length):
            next_good = good[pos + 1]
            must_match = required_match[pos]

            for character, target in enumerate(transition[state]):
                completes_match = target == m
                if completes_match != must_match:
                    continue

                next_state = fallback if completes_match else target
                if next_good & (1 << next_state):
                    answer.append(chr(ord('a') + character))
                    state = next_state
                    break

        return "".join(answer)

