                # The substring consisting only of this digit.
                current[digit % divisor] = 1

                # Extend every substring ending at the previous position.
                for remainder, count in enumerate(dp[divisor]):
                    current[(remainder * 10 + digit) % divisor] += count

                dp[divisor] = current

            if digit != 0:
                answer += dp[digit][0]

        return answer

import sys


def main():
    s = sys.stdin.buffer.readline().strip()
    rev = s[::-1]
    n = len(s)

    # Build the KMP prefix function for the reversed string.
    pi = [0] * n
    matched = 0
    for i in range(1, n):
        ch = rev[i]
        while matched > 0 and rev[matched] != ch:
            matched = pi[matched - 1]
        if rev[matched] == ch:
            matched += 1
        pi[i] = matched

    # Find the longest prefix of rev that is a suffix of s.
    # This is exactly the longest palindromic suffix of s.
    matched = 0
    for ch in s:
        while matched > 0 and rev[matched] != ch:
            matched = pi[matched - 1]
        if rev[matched] == ch:
            matched += 1

    sys.stdout.buffer.write(s + rev[matched:] + b"\n")


if __name__ == "__main__":
    main()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = str2.encode("ascii")
        word = bytearray(length)

        # Place all required occurrences, checking overlapping assignments.
        forced_end = 0
        for i, flag in enumerate(str1):
            if flag == "T":
                overlap = forced_end - i
                if overlap > 0 and word[i:forced_end] != pattern[:overlap]:
                    return ""
                word[i:i + m] = pattern
                forced_end = i + m

        # Use 'a' everywhere else and record the rightmost non-forced position.
        last_free = [-1] * length
        latest = -1
        for i in range(length):
            if word[i] == 0:
                word[i] = ord('a')
                latest = i
            last_free[i] = latest

        # Break forbidden occurrences at the latest possible free position.
        for i, flag in enumerate(str1):
            if flag == "F" and word.startswith(pattern, i):
                pos = last_free[i + m - 1]
                if pos < i:
                    return ""
                word[pos] = ord('b')

        return word.decode("ascii")

from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        # Map the boundary to clockwise positions on a circle.
        positions = []
        for x, y in points:
            if y == 0:
                positions.append(x)
            elif x == side:
                positions.append(side + y)
            elif y == side:
                positions.append(3 * side - x)
            else:
                positions.append(perimeter - y)

        positions.sort()
        n = len(positions)
        doubled = positions + [p + perimeter for p in positions]
        size = 2 * n

        def feasible(distance: int) -> bool:
            # jump[i] is the earliest point at least distance after point i.
            # size is a sentinel that points to itself.
            jump = [size] * (size + 1)
            right = 0

            for left in range(size):
                target = doubled[left] + distance
                while right < size and doubled[right] < target:
                    right += 1
                jump[left] = right

            # Perform k - 1 greedy jumps from every possible starting point.
            reached = list(range(n))
            steps = k - 1

            while steps:
                if steps & 1:
                    reached = [jump[index] for index in reached]
                steps >>= 1
                if steps:
                    jump = [jump[index] for index in jump]

            # The final gap, wrapping back to the start, must also be large enough.
            maximum_span = perimeter - distance
            return any(
                end < size and doubled[end] - doubled[start] <= maximum_span
                for start, end in enumerate(reached)
            )

        # k >= 4 implies the answer <= perimeter // k <= side.
        # For distances <= side, circular spacing and Manhattan constraints agree.
        low, high = 0, perimeter // k

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low
